#!/usr/bin/env python3
"""Regenerate PROOF.bend: the mechanical case-split proofs for P1-P7.

The proofs are finite case analyses; Bend has no tactics, so the cases are
written out. Run `python3 gen_proof.py > PROOF.bend` after adding a state.
Everything the generator emits is rechecked by `bend PROOF.bend --verdict`.
"""

STATES = ["Candidate", "SandboxEvaluated", "Shadowed", "Approved", "Active", "Proven", "Retired"]

HEADER = """# Policy lifecycle: the proofs.
#
# Agent-written (generated by gen_proof.py, then rechecked by Bend). Each
# `def Laws.<name>` proves the law of the same name in LAWS.bend.
# Gate: `bend PROOF.bend --verdict` must print ALL PROOFS CHECK.

import Base
import ./Model.bend as M
import ./SPEC.bend as S
import ./LAWS.bend as Laws
"""

def ind(n):
    return "  " * n

def pair_split(depth, leaf="{==}"):
    """match f / match t over every state pair; the leaf is closed by computation."""
    out = [f"{ind(depth)}match f:"]
    for f in STATES:
        out.append(f"{ind(depth+1)}case M.{f}{{}}:")
        out.append(f"{ind(depth+2)}match t:")
        for t in STATES:
            out.append(f"{ind(depth+3)}case M.{t}{{}}:")
            out.append(f"{ind(depth+4)}{leaf}")
    return out

def single_split(var, depth, leaf_fn):
    out = [f"{ind(depth)}match {var}:"]
    for s in STATES:
        out.append(f"{ind(depth+1)}case M.{s}{{}}:")
        out.extend(leaf_fn(s, depth + 2))
    return out

# Captain-required targets and legal edges are *not* used here: the generator
# only enumerates structure, and Bend decides each leaf by computation.
NEEDS_CAPTAIN = {"Approved", "Active", "Proven", "Retired"}

def p2():
    out = ["def Laws.p2_captain_gate(c, t, f, p):", f"{ind(1)}match c:",
           f"{ind(2)}case True{{}}:", f"{ind(3)}{{==}}", f"{ind(2)}case False{{}}:"]
    def leaf(t, d):
        if t in NEEDS_CAPTAIN:
            return [f"{ind(d)}match f:"] + sum(
                ([f"{ind(d+1)}case M.{f}{{}}:", f"{ind(d+2)}{{==}}"] for f in STATES), [])
        return [f"{ind(d)}{{==}}"]
    out.extend(single_split("t", 3, leaf))
    return out

def p7(name, target_pred, field, target):
    # p, then the evidence flag, then t, then f (and c where legality+Captain pass).
    out = [f"def Laws.{name}(p, t, f, c):", f"{ind(1)}match p:",
           f"{ind(2)}case M.Pre{{eval_pass, shadow_ok, shadow_present, proven_ok}}:",
           f"{ind(3)}match {field}:"]
    for val in ("True", "False"):
        out.append(f"{ind(4)}case {val}{{}}:")
        if val == "True":
            out.append(f"{ind(5)}{{==}}")
            continue
        def leaf(t, d):
            if t != target:
                return [f"{ind(d)}{{==}}"]
            lines = [f"{ind(d)}match f:"]
            for f in STATES:
                lines.append(f"{ind(d+1)}case M.{f}{{}}:")
                lines.append(f"{ind(d+2)}match c:")
                for c in ("True", "False"):
                    lines.append(f"{ind(d+3)}case {c}{{}}:")
                    lines.append(f"{ind(d+4)}{{==}}")
            return lines
        out.extend(single_split("t", 5, leaf))
    return out

def main():
    L = [HEADER]
    L.append("# P1/P4/P5: finite case analysis over every (from, to) pair; Bend decides each\n# leaf by computation. Captain approval and evidence stay symbolic.")
    for name in ("p1_pipeline", "p4_forward_only", "p5_shadow_before_approval"):
        L.append(f"def Laws.{name}(f, t, c, p):")
        L.extend(pair_split(1))
        L.append("")
    L.append("# P2: with c = True the conclusion is immediate; with c = False every\n# Captain-required target is rejected whatever the source state.")
    L.extend(p2()); L.append("")
    L.append("# P3: `legal` out of `retired` is False for every target, and False absorbs `and`.")
    L.extend(["def Laws.p3_terminal(t, c, p):", f"{ind(1)}{{==}}", ""])
    L.append("# P3': induction on the sequence. A step out of `retired` is rejected (P3),\n# so `next` leaves the state at `retired` and the induction hypothesis applies.")
    L.extend(["def Laws.p3_terminal_sequences(steps):", f"{ind(1)}match steps:",
              f"{ind(2)}case M.NoMore{{}}:", f"{ind(3)}{{==}}", f"{ind(2)}case M.Attempt{{h, tl}}:",
              f"{ind(3)}match h:", f"{ind(4)}case M.Step{{to, cap, pre}}:",
              f"{ind(5)}Laws.p3_terminal_sequences(tl)", ""])
    L.append("# P6: `finish` only ever builds Promoted{_, False, False}.")
    L.extend(["def finish_no_authority(ok: Bool, t: M.State) -> {S.grants_authority(M.finish(ok, t)) == False{} : Bool}:",
              f"{ind(1)}match ok:", f"{ind(2)}case True{{}}:", f"{ind(3)}{{==}}",
              f"{ind(2)}case False{{}}:", f"{ind(3)}{{==}}", "",
              "def Laws.p6_no_authority_grant(f, t, c, p):",
              f"{ind(1)}finish_no_authority(M.decide(f, t, c, p), t)", ""])
    # P8-P10: lemmas over the decision result `ok`, then instantiated at `decide(...)`.
    def match_states(var, depth):
        out = [f"{ind(depth)}match {var}:"]
        for s in STATES:
            out += [f"{ind(depth+1)}case M.{s}{{}}:", f"{ind(depth+2)}{{==}}"]
        return out
    L.append("# P8: lemmas over the decision result, instantiated at decide(...).")
    L.append("def next_rejected(ok: Bool, +t: M.State, +f: M.State) -> {Bool.or(ok, S.eq(S.stage(M.pick(ok, t, f)), S.stage(f))) == True{} : Bool}:")
    L.append(f"{ind(1)}match ok:")
    L += [f"{ind(2)}case True{{}}:", f"{ind(3)}{{==}}", f"{ind(2)}case False{{}}:"] + match_states("f", 3)
    L += ["", "def Laws.p8a_rejected_stays(f, t, c, p):", f"{ind(1)}next_rejected(M.decide(f, t, c, p), t, f)", ""]
    L.append("def next_accepted(ok: Bool, +t: M.State, +f: M.State) -> {Bool.or(Bool.not(ok), S.eq(S.stage(M.pick(ok, t, f)), S.stage(t))) == True{} : Bool}:")
    L.append(f"{ind(1)}match ok:")
    L += [f"{ind(2)}case True{{}}:"] + match_states("t", 3) + [f"{ind(2)}case False{{}}:", f"{ind(3)}{{==}}"]
    L += ["", "def Laws.p8b_accepted_lands(f, t, c, p):", f"{ind(1)}next_accepted(M.decide(f, t, c, p), t, f)", ""]
    L += ["# P9: both laws are the definition of `run`; Bend checks them by computation.",
          "def Laws.p9a_run_empty(s):", f"{ind(1)}{{==}}", "",
          "def Laws.p9b_run_step(to, cap, pre, tl, s):", f"{ind(1)}{{==}}", ""]
    L.append("# P10: apply = finish(decide, t); check finish against the decision.")
    L.append("def outcome_lemma(ok: Bool, +t: M.State) -> {S.outcome_agrees(ok, t, M.finish(ok, t)) == True{} : Bool}:")
    L.append(f"{ind(1)}match ok:")
    L += [f"{ind(2)}case True{{}}:"] + match_states("t", 3) + [f"{ind(2)}case False{{}}:", f"{ind(3)}{{==}}"]
    L += ["", "def Laws.p10_outcome_agrees(f, t, c, p):", f"{ind(1)}outcome_lemma(M.decide(f, t, c, p), t)", ""]
    L.append("# P7: split the evidence flag; when it is False the target is rejected, which\n# needs the source state (and Captain approval) only for the gated target.")
    L.extend(p7("p7a_sandbox_needs_eval_pass", "is_sandbox_evaluated", "eval_pass", "SandboxEvaluated")); L.append("")
    L.extend(p7("p7b_shadowed_needs_shadow_ok", "is_shadowed", "shadow_ok", "Shadowed")); L.append("")
    L.extend(p7("p7c_approved_needs_shadow_present", "is_approved", "shadow_present", "Approved")); L.append("")
    L.extend(p7("p7d_proven_needs_proven_ok", "is_proven", "proven_ok", "Proven")); L.append("")
    print("\n".join(L))

main()
